import "server-only";
import { z } from "zod";
const id = z.uuid();
const count = z.number().int().min(0).max(1_000_000_000);
export const usageCodes = [
  "SETTLEMENT_FAILED",
  "UNCERTAIN",
  "PREPARATION_DEFERRED",
  "WORKER_FAILED",
  "PUBLICATION_DELAY",
  "PUBLICATION_FAILED",
  "COUNTER_DRIFT",
  "MISSING_ACCOUNTING",
  "UNCERTAINTY_OLDER_THAN_15_MINUTES",
  "OUTSTANDING_ORPHAN",
  "REPAIR_FAILED",
] as const;
const schemas = {
  auth: z.object({ code: z.enum(["AUTH_FAILED", "AUTH_WARNING"]) }),
  usage: z.object({
    code: z.enum(usageCodes),
    userId: id,
    sendId: id.optional(),
  }),
  gmail: z.object({
    category: z.enum([
      "LOCAL_PERMANENT",
      "RECONNECT_REQUIRED",
      "UNAUTHORIZED",
      "OWNER_THROTTLE",
      "PROVIDER_DAILY_LIMIT",
      "PROJECT_DAILY_LIMIT",
      "DOMAIN_POLICY",
      "MESSAGE_REJECTED",
      "PREPARATION_TRANSIENT",
      "UNCERTAIN",
    ]),
    status: z.number().int().min(0).max(599),
  }),
  webhook: z.object({
    code: z.enum([
      "WEBHOOK_ID_CONFLICT",
      "WEBHOOK_FAILED",
      "WEBHOOK_QUARANTINED",
    ]),
    receiptId: id,
  }),
  billing: z.object({
    code: z.literal("BILLING_RECONCILIATION_FAILED"),
    subscriptionRecordId: id,
  }),
  nightly: z.object({
    scanned: count,
    failed: count,
    missingSettlement: count,
    quarantined: count,
    staleInbox: count,
    conflictingSubscriptions: count,
    complete: z.boolean(),
  }),
  lifecycle: z.object({ code: z.literal("OWNER_RETRY_PENDING"), count }),
  worker: z.object({
    code: z.enum(["WORKER_FAILURE", "SDK_DIAGNOSTIC"]),
  }),
} as const;
export type OperationalEvent = keyof typeof schemas;
// Input is unknown even to typed callers. Schemas strip extra keys and validate
// values (a token under an allowed key is still rejected). No Error serialization.
export function safeLog(
  level: "debug" | "info" | "warn" | "error",
  event: OperationalEvent,
  input: unknown,
) {
  if (!Object.hasOwn(schemas, event)) return;
  const result = schemas[event].safeParse(input);
  if (!result.success) return;
  const payload = { event, ...result.data };
  console[level](JSON.stringify(payload));
}
export function safeWorkerError() {
  const error = new Error("WORKER_FAILURE");
  error.stack = "Error: WORKER_FAILURE";
  return error;
}
// SDK log arguments can include full HTTP requests and nested errors. Discard all
// arguments; SDK diagnostics retain only the fixed event and level.
export const safeSdkLogger = {
  debug: () => safeLog("debug", "worker", { code: "SDK_DIAGNOSTIC" }),
  info: () => safeLog("info", "worker", { code: "SDK_DIAGNOSTIC" }),
  warn: () => safeLog("warn", "worker", { code: "SDK_DIAGNOSTIC" }),
  error: () => safeLog("error", "worker", { code: "SDK_DIAGNOSTIC" }),
};
